fn solve(n: i8, k: i8) -> Vec<i8> {
    // Number of unselected items
    let unselected = n - k;

    // If nothing or everything is selected, the only possible "good" unselected count is 0
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise at least one "good" unselected item is possible
    let x_min = 1;

    // Compute twice the selected count, saturating on overflow to avoid i8 wrapping
    let twice_k = k.saturating_mul(2);

    // The maximum good unselected items is min(unselected, 2*k)
    let x_max = if twice_k < unselected {
        twice_k
    } else {
        unselected
    };

    vec![x_min, x_max]
}

